"""One-page Figure 1 overview. All photographs are original project stimuli.

The image payload at the end makes this plotting source self-contained. SVG
text remains editable; no outcome data or inferential statistics are simulated.
Requires Python, matplotlib, numpy and Pillow.
"""
from pathlib import Path
from io import BytesIO
import base64
import json
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from matplotlib.patches import FancyBboxPatch, FancyArrowPatch, Rectangle
from PIL import Image

import os
OSFROOT=Path(__file__).resolve().parents[2]
OUT=Path(os.environ.get('OSF_REPRO_OUT',OSFROOT/'figures/regenerated'))/'main'
OUT.mkdir(parents=True,exist_ok=True)
ROOT=OSFROOT
W, H = 1800, 2260
C = dict(ink='#232C3A', muted='#617083', line='#D1D9E1', pale='#F5F7FA',
         violet='#6655A4', violetp='#F0ECF8', teal='#177E81', tealp='#EAF5F3',
         human='#566579', humanp='#EDF0F4', rose='#A85D78', rosep='#F9EEF2')
plt.rcParams.update({'font.family':'Arial', 'svg.fonttype':'none',
                     'pdf.fonttype':42, 'text.color':C['ink'],
                     'font.size':8, 'axes.unicode_minus':False})
fig=plt.figure(figsize=(180/25.4,226/25.4), facecolor='white')
ax=fig.add_axes([0,0,1,1]); ax.set(xlim=(0,W),ylim=(H,0)); ax.axis('off')

def text(x,y,s,size=27,color=None,bold=False,ha='left',va='top',rotation=0):
    return ax.text(x,y,s,fontsize=size*72/254,color=color or C['ink'],
                   weight='bold' if bold else 'normal',ha=ha,va=va,
                   linespacing=1.32,rotation=rotation)
def box(x,y,w,h,fc=None,ec=None,r=10,lw=.65):
    p=FancyBboxPatch((x,y),w,h,boxstyle=f'round,pad=0,rounding_size={r}',
                     facecolor=fc or C['pale'],edgecolor=ec or 'none',linewidth=lw)
    ax.add_patch(p);return p
def line(x1,y1,x2,y2,color=None,lw=.7):
    ax.plot([x1,x2],[y1,y2],color=color or C['line'],lw=lw)
def arrow(x1,y1,x2,y2,color=None,lw=.9,style='-|>',connection='arc3,rad=0'):
    p=FancyArrowPatch((x1,y1),(x2,y2),arrowstyle=style,mutation_scale=7,
                     linewidth=lw,color=color or C['muted'],shrinkA=2,shrinkB=2,
                     connectionstyle=connection)
    ax.add_patch(p);return p
def panel(letter,title,y,subtitle=None):
    text(40,y,letter,36,bold=True)
    text(87,y+1,title,31,bold=True)
    if subtitle: text(87,y+45,subtitle,25,C['muted'])
def image(key,x,y,w,h=None):
    h=w if h is None else h
    aa=fig.add_axes([x/W,1-(y+h)/H,w/W,h/H]);aa.axis('off')
    aa.imshow(Image.open(BytesIO(base64.b64decode(ASSETS[key]['png']))))
    return aa
def chip(x,y,w,s,color,fc,size=24):
    box(x,y,w,42,fc)
    text(x+w/2,y+10,s,size,color,bold=True,ha='center')

def draw():
    # a. Inputs and independent sources of evidence.
    panel('a','One stimulus space, two frozen models',28)
    for rr in range(3):
        for cc in range(3):image(f'mosaic_{rr}_{cc}',89+cc*80,105+rr*80,75)
    text(209,82,'Lighting',23,C['muted'],ha='center')
    text(63,218,'Shape',23,C['muted'],ha='center',va='center',rotation=90)
    text(362,112,'3,888 rendered test images',30,bold=True)
    text(362,160,'36 shapes × 36 illuminations\n× 3 viewpoints',27)
    text(362,246,'Physical gloss and colour\nrecorded for each image',25,C['muted'])
    arrow(875,205,941,205)
    box(968,92,785,102,C['humanp'])
    text(992,111,'HUMAN BEHAVIORAL REFERENCE',23,C['human'],bold=True)
    text(992,150,'Published asymmetric gloss-matching judgments',26)
    box(968,211,785,120,C['violetp'])
    text(992,230,'FROZEN VISION–LANGUAGE MODELS',23,C['violet'],bold=True)
    text(992,269,'InternVL3.5-4B  ·  Qwen3-VL-4B-Instruct',27,bold=True)
    line(42,361,1758,361)

    # b. Prompt excerpts are verbatim; response tokens preserve the protocols.
    panel('b','Three interfaces to apparent gloss',390,
          'Fresh context for each decision; no target human ratings supplied to the models')
    cols=[62,642,1222]
    for x in cols:box(x,496,516,604,'#FAFBFC',C['line'],r=12)
    for x,n,title in zip(cols,['01','02','03'],['Single-image rating','Pairwise choice','Reference matching']):
        text(x+21,514,n,24,C['violet'],bold=True)
        text(x+70,514,title,27,bold=True)
    image('single',235,567,170)
    image('pair_a',699,567,166);image('pair_b',896,567,166)
    text(782,741,'A',23,C['muted'],ha='center');text(979,741,'B',23,C['muted'],ha='center')
    image('match',1279,567,166);image('reference_mid',1476,567,166)
    text(1362,741,'A: test',23,C['muted'],ha='center');text(1559,741,'B: reference',23,C['muted'],ha='center')
    text(88,787,'“Rate the apparent glossiness\nof the main object in this image.”',26)
    text(668,787,'“Which object\'s surface looks glossier?”',26)
    text(1248,787,'“Which object looks glossier?\nJudge gloss, not overall brightness.”',26)
    chip(88,882,464,'Integer score: 0–100',C['violet'],C['violetp'],26)
    chip(668,882,464,'Choice: A / B / tie',C['violet'],C['violetp'],26)
    chip(1248,882,464,'Choice: A / B / SAME',C['violet'],C['violetp'],26)
    text(88,949,'Visible appearance, not\nmaterial identity or physical reflectance',25,C['muted'])
    text(668,949,'Repeat every image pair\nin both display orders',25,C['muted'])
    text(1248,949,'Update reference → compare again',25,C['teal'],bold=True)
    text(1248,987,'52 reconstructed reference levels\nTwo starts; at most 7 decisions per match',24,C['muted'])
    for x,s in zip(cols,['One score per test image','One judgment per ordered pair','One matching value per search']):
        text(x+258,1060,s,24,C['ink'],ha='center')
    arrow(899,1110,899,1150,C['violet'])

    # c. Three distinct questions, without miniature decorative result plots.
    panel('c','Does a common appearance judgment organize behavior?',1161)
    cards=[(62,'Human alignment','Fig. 2',C['teal'],C['tealp']),
           (642,'Condition geometry','Fig. 3',C['violet'],C['violetp']),
           (1222,'Cross-task transfer','Fig. 4',C['rose'],C['rosep'])]
    for x,title,figno,co,fc in cards:
        box(x,1233,516,238,fc)
        text(x+22,1254,title,28,co,bold=True)
        text(x+490,1257,figno,23,co,ha='right')
    text(84,1310,'Model judgments ↔ human judgments',25)
    text(84,1354,'Control physical gloss; test pairs where\nhuman and physical rankings disagree',24,C['muted'])
    text(664,1310,'Condition profiles → distances → RSA',25)
    text(664,1354,'Compare shape and illumination effects\nafter adjusting physical gloss and colour',24,C['muted'])
    text(1244,1310,'Rating ↔ matching → pairwise choice',25)
    text(1244,1354,'Predict one task from another;\nhold out shapes or illuminations',24,C['muted'])
    line(42,1510,1758,1510)

    # d. Backbone is frozen, whereas an external readout is explicitly supervised.
    panel('d','Locate predictive signals, then perturb a reference-defined direction',1540)
    image('single',73,1621,111)
    arrow(197,1677,252,1677)
    for x,w,title,sub,co,fc in [(265,330,'Vision encoder','Image features',C['teal'],C['tealp']),
                             (690,330,'Visual–language bridge','Visual tokens',C['violet'],C['violetp']),
                             (1115,330,'Language model','Pre-answer states',C['rose'],C['rosep'])]:
        box(x,1614,w,114,fc)
        text(x+w/2,1636,title,26,co,bold=True,ha='center')
        text(x+w/2,1680,sub,24,C['muted'],ha='center')
    arrow(608,1677,679,1677);arrow(1033,1677,1104,1677)
    arrow(1458,1677,1520,1677)
    box(1532,1632,219,88,C['humanp'])
    text(1641,1653,'Gloss judgment',26,bold=True,ha='center')
    # Hooks branch from all stages to readout without suggesting base-model fitting.
    for x in [430,855,1280]:line(x,1730,x,1753,C['line'])
    line(430,1753,1280,1753,C['line']);arrow(430,1753,430,1811,C['teal'])
    line(899,1800,899,2195,C['line'])
    text(65,1810,'SUPERVISED READOUT',24,C['teal'],bold=True)
    text(842,1810,'Fig. 5',23,C['teal'],ha='right')
    chip(65,1863,353,'Pooled internal states',C['teal'],C['tealp'],25)
    chip(491,1863,351,'Human training labels',C['human'],C['humanp'],25)
    arrow(242,1914,345,1963,C['teal']);arrow(667,1914,565,1963,C['human'])
    box(284,1970,338,60,C['tealp'],C['teal'])
    text(453,1987,'Fit a separate ridge probe',25,C['teal'],bold=True,ha='center')
    arrow(453,2038,453,2080,C['teal'])
    text(453,2095,'Predict human judgments for\nheld-out shapes / illuminations',26,ha='center')
    text(453,2182,'Base-model weights remain frozen',24,C['muted'],ha='center')
    # Reference-only direction is conceptually separate from human-label probes.
    text(948,1810,'FUNCTIONAL INTERVENTION',24,C['violet'],bold=True)
    text(1750,1810,'Fig. 6',23,C['violet'],ha='right')
    image('reference_low',963,1865,88);image('reference_mid',1062,1865,88);image('reference_high',1161,1865,88)
    text(1106,1963,'Reference sequence',23,C['muted'],ha='center')
    arrow(1257,1910,1303,1910,C['violet'])
    box(1312,1865,421,87,C['violetp'])
    text(1522,1885,'Define a gloss-related direction',25,C['violet'],bold=True,ha='center')
    text(1522,1924,'from reference-token responses',23,C['muted'],ha='center')
    arrow(1522,1960,1522,2001,C['violet'])
    box(966,2010,767,67,C['violetp'],C['violet'])
    text(1349,2031,'Add / subtract direction at test-image visual tokens',25,C['violet'],bold=True,ha='center')
    arrow(1349,2085,1349,2110,C['violet'])
    text(1349,2122,'Measure changes in gloss choice and matching',25,ha='center')
    text(1349,2170,'Direction defined without human judgments',24,C['muted'],ha='center')
    text(1349,2210,'Brightness and random-direction controls',24,C['muted'],ha='center')

    for ext in ['pdf','png']:
        fig.savefig(OUT/f'Fig1_overview.{ext}',dpi=320,facecolor='white')
    fig.savefig(OUT/'Figure1_Overview_EN.svg',dpi=450,facecolor='white')
    plt.close(fig)

ASSETS = {'mosaic_0_0': {'source': 'images_processed/512x512/gloss/img1.png', 'png': ''}, 'mosaic_0_1': {'source': 'images_processed/512x512/gloss/img1297.png', 'png': ''}, 'mosaic_0_2': {'source': 'images_processed/512x512/gloss/img2593.png', 'png': ''}, 'mosaic_1_0': {'source': 'images_processed/512x512/gloss/img37.png', 'png': ''}, 'mosaic_1_1': {'source': 'images_processed/512x512/gloss/img1333.png', 'png': ''}, 'mosaic_1_2': {'source': 'images_processed/512x512/gloss/img2629.png', 'png': ''}, 'mosaic_2_0': {'source': 'images_processed/512x512/gloss/img73.png', 'png': ''}, 'mosaic_2_1': {'source': 'images_processed/512x512/gloss/img1369.png', 'png': ''}, 'mosaic_2_2': {'source': 'images_processed/512x512/gloss/img2665.png', 'png': ''}, 'single': {'source': 'images_processed/512x512/gloss/img1.png', 'png': ''}, 'pair_a': {'source': 'images_processed/512x512/gloss/img2462.png', 'png': ''}, 'pair_b': {'source': 'images_processed/512x512/gloss/img3648.png', 'png': ''}, 'match': {'source': 'images_processed/512x512/gloss/img1889.png', 'png': ''}, 'reference_low': {'source': 'mllm_material/reference_reconstruction_v3/output/reference_01.png', 'png': ''}, 'reference_mid': {'source': 'mllm_material/reference_reconstruction_v3/output/reference_27.png', 'png': ''}, 'reference_high': {'source': 'mllm_material/reference_reconstruction_v3/output/reference_52.png', 'png': ''}}

if __name__ == '__main__':
    draw()
